"use strict";(self.webpackChunkprompt_labs=self.webpackChunkprompt_labs||[]).push([[5459],{61495:e=>{e.exports=JSON.parse('{"version":{"pluginId":"orchestrator","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"orchestratorSidebar":[{"type":"link","href":"/system-prompts/orchestrator/","label":"Overview","docId":"README","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/AGENT","label":"Agent Orchestrator","docId":"AGENT","unlisted":false},{"type":"category","label":"Skills","items":[{"type":"link","href":"/system-prompts/orchestrator/skills/api-integration","label":"Skill: API Integration & External Services","docId":"skills/api-integration","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/browser-automation","label":"Skill: Browser Automation","docId":"skills/browser-automation","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/code-execution","label":"Skill: Code Execution & Shell","docId":"skills/code-execution","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/code-quality-testing","label":"Skill: Code Quality & Testing","docId":"skills/code-quality-testing","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/codebase-understanding","label":"Skill: Codebase Understanding (GitNexus)","docId":"skills/codebase-understanding","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/communication-tone","label":"Skill: Communication & Tone","docId":"skills/communication-tone","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/data-analysis","label":"Skill: Data Analysis & Processing","docId":"skills/data-analysis","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/deployment","label":"Skill: Deployment","docId":"skills/deployment","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-accessibility-review","label":"/accessibility-review","docId":"skills/design-accessibility-review","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-design-critique","label":"/design-critique","docId":"skills/design-design-critique","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-design-handoff","label":"/design-handoff","docId":"skills/design-design-handoff","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-design-system","label":"/design-system","docId":"skills/design-design-system","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-research-synthesis","label":"/research-synthesis","docId":"skills/design-research-synthesis","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-user-research","label":"User Research","docId":"skills/design-user-research","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/design-ux-copy","label":"/ux-copy","docId":"skills/design-ux-copy","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/doc-coauthoring","label":"Doc Co-Authoring Workflow","docId":"skills/doc-coauthoring","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/docx-skill","label":"DOCX creation, editing, and analysis","docId":"skills/docx-skill","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-architecture","label":"/architecture","docId":"skills/engineering-architecture","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-code-review","label":"/code-review","docId":"skills/engineering-code-review","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-debug","label":"/debug","docId":"skills/engineering-debug","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-deploy-checklist","label":"/deploy-checklist","docId":"skills/engineering-deploy-checklist","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-documentation","label":"Technical Documentation","docId":"skills/engineering-documentation","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-incident-response","label":"/incident-response","docId":"skills/engineering-incident-response","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-standup","label":"/standup","docId":"skills/engineering-standup","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-system-design","label":"System Design","docId":"skills/engineering-system-design","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-tech-debt","label":"Tech Debt Management","docId":"skills/engineering-tech-debt","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/engineering-testing-strategy","label":"Testing Strategy","docId":"skills/engineering-testing-strategy","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/file-operations","label":"Skill: File Operations","docId":"skills/file-operations","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/image-media","label":"Skill: Image & Media Handling","docId":"skills/image-media","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/learn","label":"Learning Mode","docId":"skills/learn","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/memory-management","label":"Skill: Memory & Context Management","docId":"skills/memory-management","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/project-scaffolding","label":"Skill: Project Scaffolding","docId":"skills/project-scaffolding","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/review-pull-request","label":"Skill: Pull Request Review (Review Pull Request)","docId":"skills/review-pull-request","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/review-software-architecture","label":"Skill: Software Architecture Review (Review Software Architecture)","docId":"skills/review-software-architecture","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/safety-profiles","label":"Skill: Safety Profiles","docId":"skills/safety-profiles","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/security-audit-codebase","label":"Skill: Codebase Security Audit (Security Audit Codebase)","docId":"skills/security-audit-codebase","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/skill-creator","label":"Skill Creator","docId":"skills/skill-creator","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/web-artifacts-builder","label":"Web Artifacts Builder","docId":"skills/web-artifacts-builder","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/skills/web-search-research","label":"Skill: Web Search & Research","docId":"skills/web-search-research","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Workflows","items":[{"type":"link","href":"/system-prompts/orchestrator/workflows/agent-loop","label":"Workflow: Agent Loop","docId":"workflows/agent-loop","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/diagnostic-fix","label":"Workflow: Diagnostic-then-Fix","docId":"workflows/diagnostic-fix","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/direct-implementation","label":"Workflow: Direct Implementation","docId":"workflows/direct-implementation","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/heartbeat-monitoring","label":"Workflow: Heartbeat Monitoring & System Health","docId":"workflows/heartbeat-monitoring","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/pair-programming","label":"Workflow: Interactive Pair Programming","docId":"workflows/pair-programming","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/plan-execute","label":"Workflow: Plan-then-Execute","docId":"workflows/plan-execute","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/research-answer","label":"Workflow: Research-then-Answer","docId":"workflows/research-answer","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/spec-driven","label":"Kiro AI-Driven Development Lifecycle: Complete Methodology Instructions","docId":"workflows/spec-driven","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/summarization","label":"Workflow: Session Summarization","docId":"workflows/summarization","unlisted":false},{"type":"link","href":"/system-prompts/orchestrator/workflows/turnaround-builder","label":"Workflow: Turnaround Builder","docId":"workflows/turnaround-builder","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"AGENT":{"id":"AGENT","title":"Central AI Agent Orchestrator","description":"A. Identity & Operating Principles","sidebar":"orchestratorSidebar"},"README":{"id":"README","title":"Prompt Orchestrator","description":"A master AI agent orchestrator framework distilled from 73 leaked platform prompts. Extracts best practices from Anthropic, OpenAI, Gemini, Grok, Cursor, Windsurf, Cline, Kiro, Manus, and 65+ more platforms into reusable skills, workflows, and a central orchestrator system prompt.","sidebar":"orchestratorSidebar"},"skills/api-integration":{"id":"skills/api-integration","title":"Skill: API Integration & External Services","description":"Integrate with external APIs, REST, GraphQL, web services, SDKs, and third-party tools. Use when connecting external services, managing API keys securely, handling authentication (OAuth, JWT, API keys), implementing network retry logic, or configuring HTTP client libraries.","sidebar":"orchestratorSidebar"},"skills/browser-automation":{"id":"skills/browser-automation","title":"Skill: Browser Automation","description":"Navigate, interact with, and extract data from web pages programmatically. Trigger with \\"browse web page\\", \\"automate browser\\", \\"extract from URL\\", or when performing web scraping, form filling, DOM element inspection, or UI interaction.","sidebar":"orchestratorSidebar"},"skills/code-execution":{"id":"skills/code-execution","title":"Skill: Code Execution & Shell","description":"Execute shell commands, run code, manage processes, and interact with the operating system environment safely. Use when running terminal commands, build tools, background services, cross-platform scripts (Linux, macOS, Windows), or managing process lifecycles.","sidebar":"orchestratorSidebar"},"skills/code-quality-testing":{"id":"skills/code-quality-testing","title":"Skill: Code Quality & Testing","description":"Write clean, runnable, tested code and execute unit/integration test suites and linter passes. Trigger with \\"run tests\\", \\"fix test failure\\", \\"add unit tests\\", or when debugging root causes, verifying immediate code runnability, or enforcing coding standards.","sidebar":"orchestratorSidebar"},"skills/codebase-understanding":{"id":"skills/codebase-understanding","title":"Skill: Codebase Understanding (GitNexus)","description":"Leverage the GitNexus knowledge graph and call traces to understand codebase structure, execution flows, symbol dependencies, and blast radius. Trigger with \\"understand codebase\\", \\"trace call flow\\", \\"impact analysis\\", \\"what calls X\\", or when navigating unfamiliar code architectures.","sidebar":"orchestratorSidebar"},"skills/communication-tone":{"id":"skills/communication-tone","title":"Skill: Communication & Tone","description":"Enforce anti-fluff communication, precise technical tone, zero sycophancy, minimal token consumption, and direct Markdown/code formatting. Use across all conversation turns to eliminate filler phrases, ungrounded speculation, and conversational preamble.","sidebar":"orchestratorSidebar"},"skills/data-analysis":{"id":"skills/data-analysis","title":"Skill: Data Analysis & Processing","description":"Analyze, transform, clean, and visualize structured datasets using Python REPL, pandas, numpy, and plotting libraries. Trigger with \\"analyze data\\", \\"process CSV\\", \\"EDA\\", \\"generate plots\\", \\"statistical summary\\", or when computing numerical results.","sidebar":"orchestratorSidebar"},"skills/deployment":{"id":"skills/deployment","title":"Skill: Deployment","description":"Deploy applications, configure cloud hosting targets (Vercel, Netlify, GitHub Pages, S3), manage build pipelines, and verify post-deployment health. Trigger with \\"deploy app\\", \\"publish release\\", \\"setup hosting\\", or when configuring production rollout workflows.","sidebar":"orchestratorSidebar"},"skills/design-accessibility-review":{"id":"skills/design-accessibility-review","title":"/accessibility-review","description":"Run a WCAG 2.1 AA accessibility audit on a design or page. Trigger with \\"audit accessibility\\", \\"check a11y\\", \\"is this accessible?\\", or when reviewing a design for color contrast, keyboard navigation, touch target size, or screen reader behavior before handoff.","sidebar":"orchestratorSidebar"},"skills/design-design-critique":{"id":"skills/design-design-critique","title":"/design-critique","description":"Get structured design feedback on usability, hierarchy, and consistency. Trigger with \\"review this design\\", \\"critique this mockup\\", \\"what do you think of this screen?\\", or when sharing a Figma link or screenshot for feedback at any stage from exploration to final polish.","sidebar":"orchestratorSidebar"},"skills/design-design-handoff":{"id":"skills/design-design-handoff","title":"/design-handoff","description":"Generate developer handoff specs from a design. Use when a design is ready for engineering and needs a spec sheet covering layout, design tokens, component props, interaction states, responsive breakpoints, edge cases, and animation details.","sidebar":"orchestratorSidebar"},"skills/design-design-system":{"id":"skills/design-design-system","title":"/design-system","description":"Audit, document, or extend your design system. Use when checking for naming inconsistencies or hardcoded values across components, writing documentation for a component\'s variants, states, and accessibility notes, or designing a new pattern that fits the existing system.","sidebar":"orchestratorSidebar"},"skills/design-research-synthesis":{"id":"skills/design-research-synthesis","title":"/research-synthesis","description":"Synthesize user research into themes, insights, and recommendations. Use when you have interview transcripts, survey results, usability test notes, support tickets, or NPS responses that need to be distilled into patterns, user segments, and prioritized next steps.","sidebar":"orchestratorSidebar"},"skills/design-user-research":{"id":"skills/design-user-research","title":"User Research","description":"Plan, conduct, and synthesize user research. Trigger with \\"user research plan\\", \\"interview guide\\", \\"usability test\\", \\"survey design\\", \\"research questions\\", or when the user needs help with any aspect of understanding their users through research.","sidebar":"orchestratorSidebar"},"skills/design-ux-copy":{"id":"skills/design-ux-copy","title":"/ux-copy","description":"Write or review UX copy \u2014 microcopy, error messages, empty states, CTAs. Trigger with \\"write copy for\\", \\"what should this button say?\\", \\"review this error message\\", or when naming a CTA, wording a confirmation dialog, filling an empty state, or writing onboarding text.","sidebar":"orchestratorSidebar"},"skills/doc-coauthoring":{"id":"skills/doc-coauthoring","title":"Doc Co-Authoring Workflow","description":"Guide users through a structured workflow for co-authoring documentation. Use when user wants to write documentation, proposals, technical specs, decision docs, or similar structured content. This workflow helps users efficiently transfer context, refine content through iteration, and verify the doc works for readers. Trigger when user mentions writing docs, creating proposals, drafting specs, or similar documentation tasks.","sidebar":"orchestratorSidebar"},"skills/docx-skill":{"id":"skills/docx-skill","title":"DOCX creation, editing, and analysis","description":"Use this skill whenever the user wants to create, read, edit, or manipulate Word documents (.docx files) or Word templates (.dotx files). Triggers include: any mention of \'Word doc\', \'word document\', \'.docx\', \'.dotx\', or requests to produce professional documents with formatting like tables of contents, headings, page numbers, or letterheads. Also use when extracting or reorganizing content from .docx or .dotx files, inserting or replacing images in documents, performing find-and-replace in Word files, working with tracked changes or comments, or converting content into a polished Word document. If the user asks for a \'report\', \'memo\', \'letter\', \'template\', or similar deliverable as a Word or .docx file, use this skill. Do NOT use for PDFs, spreadsheets, Google Docs, or general coding tasks unrelated to document generation.","sidebar":"orchestratorSidebar"},"skills/engineering-architecture":{"id":"skills/engineering-architecture","title":"/architecture","description":"Create or evaluate an architecture decision record (ADR). Use when choosing between technologies (e.g., Kafka vs SQS), documenting a design decision with trade-offs and consequences, reviewing a system design proposal, or designing a new component from requirements and constraints.","sidebar":"orchestratorSidebar"},"skills/engineering-code-review":{"id":"skills/engineering-code-review","title":"/code-review","description":"Review code changes for security, performance, and correctness. Trigger with a PR URL or diff, \\"review this before I merge\\", \\"is this code safe?\\", or when checking a change for N+1 queries, injection risks, missing edge cases, or error handling gaps.","sidebar":"orchestratorSidebar"},"skills/engineering-debug":{"id":"skills/engineering-debug","title":"/debug","description":"Structured debugging session \u2014 reproduce, isolate, diagnose, and fix. Trigger with an error message or stack trace, \\"this works in staging but not prod\\", \\"something broke after the deploy\\", or when behavior diverges from expected and the cause isn\'t obvious.","sidebar":"orchestratorSidebar"},"skills/engineering-deploy-checklist":{"id":"skills/engineering-deploy-checklist","title":"/deploy-checklist","description":"Pre-deployment verification checklist. Use when about to ship a release, deploying a change with database migrations or feature flags, verifying CI status and approvals before going to production, or documenting rollback triggers ahead of time.","sidebar":"orchestratorSidebar"},"skills/engineering-documentation":{"id":"skills/engineering-documentation","title":"Technical Documentation","description":"Write and maintain technical documentation. Trigger with \\"write docs for\\", \\"document this\\", \\"create a README\\", \\"write a runbook\\", \\"onboarding guide\\", or when the user needs help with any form of technical writing \u2014 API docs, architecture docs, or operational runbooks.","sidebar":"orchestratorSidebar"},"skills/engineering-incident-response":{"id":"skills/engineering-incident-response","title":"/incident-response","description":"Run an incident response workflow \u2014 triage, communicate, and write postmortem. Trigger with \\"we have an incident\\", \\"production is down\\", an alert that needs severity assessment, a status update mid-incident, or when writing a blameless postmortem after resolution.","sidebar":"orchestratorSidebar"},"skills/engineering-standup":{"id":"skills/engineering-standup","title":"/standup","description":"Generate a standup update from recent activity. Use when preparing for daily standup, summarizing yesterday\'s commits and PRs and ticket moves, formatting work into yesterday/today/blockers, or structuring a few rough notes into a shareable update.","sidebar":"orchestratorSidebar"},"skills/engineering-system-design":{"id":"skills/engineering-system-design","title":"System Design","description":"Design systems, services, and architectures. Trigger with \\"design a system for\\", \\"how should we architect\\", \\"system design for\\", \\"what\'s the right architecture for\\", or when the user needs help with API design, data modeling, or service boundaries.","sidebar":"orchestratorSidebar"},"skills/engineering-tech-debt":{"id":"skills/engineering-tech-debt","title":"Tech Debt Management","description":"Identify, categorize, and prioritize technical debt. Trigger with \\"tech debt\\", \\"technical debt audit\\", \\"what should we refactor\\", \\"code health\\", or when the user asks about code quality, refactoring priorities, or maintenance backlog.","sidebar":"orchestratorSidebar"},"skills/engineering-testing-strategy":{"id":"skills/engineering-testing-strategy","title":"Testing Strategy","description":"Design test strategies and test plans. Trigger with \\"how should we test\\", \\"test strategy for\\", \\"write tests for\\", \\"test plan\\", \\"what tests do we need\\", or when the user needs help with testing approaches, coverage, or test architecture.","sidebar":"orchestratorSidebar"},"skills/file-operations":{"id":"skills/file-operations","title":"Skill: File Operations","description":"Read, write, search, and edit files across the workspace. Enforces the READ-BEFORE-WRITE rule, batch file reads, atomic SEARCH/REPLACE blocks, and file discovery via grep and glob rather than terminal commands.","sidebar":"orchestratorSidebar"},"skills/image-media":{"id":"skills/image-media","title":"Skill: Image & Media Handling","description":"Generate, edit, and process visual artifacts, diagrams, and multimedia assets. Use when creating UI mockups, visual explainers, image transformations, or media layouts (carousel, bento grid).","sidebar":"orchestratorSidebar"},"skills/learn":{"id":"skills/learn","title":"Learning Mode","description":"Use this skill when the user wants intellectual understanding \u2014 learning how or why something works, not getting a task done or soliciting Claude\'s judgment.\\n\\nTrigger for:\\n- Explicit learning requests: teach, explain, ELI5, walk me through, quiz me, flashcards, \\"I\'m rusty on\\"; definitions (\\"what is X\\")\\n- Terse concept names implying \\"help me understand this\\": \\"Galois theory,\\" \\"transformers, from scratch\\"\\n- Confusion signals: \\"won\'t stick,\\" \\"keep mixing these up,\\" \\"not getting it\\"\\n- Learning-path questions: prerequisites, sequencing, what to study before X\\n- Conceptual questions about mechanisms, causes, or dynamics\\n\\nDon\'t trigger for:\\n- Tasks: coding, writing, calculation, translation, factual lookup, news updates\\n- Personal troubleshooting; resource/textbook recommendations\\n- Claude\'s evaluative verdict: opinion prompts (\\"do you think X\\", \\"settle this\\", \\"honest take\\", \\"is X dead / still taken seriously\\") and interpretive takes (\\"was X really as harsh as people say\\")\\n","sidebar":"orchestratorSidebar"},"skills/memory-management":{"id":"skills/memory-management","title":"Skill: Memory & Context Management","description":"Persist and retrieve architectural context, user preferences, and project milestones across sessions. Use for crash-safe checkpointing, updating persistent memories, and managing context window retention.","sidebar":"orchestratorSidebar"},"skills/project-scaffolding":{"id":"skills/project-scaffolding","title":"Skill: Project Scaffolding","description":"Scaffold new applications, generate dependency manifests, and create initial directory structures. Use when initializing new codebases, setting up modern React/Vite/FastAPI stacks, or generating minimal project skeletons.","sidebar":"orchestratorSidebar"},"skills/review-pull-request":{"id":"skills/review-pull-request","title":"Skill: Pull Request Review (Review Pull Request)","description":"Conduct end-to-end pull request reviews using GitHub CLI (gh). Covers diff analysis, commit history inspection, CI check verification, severity-leveled feedback (Blocking, Suggestion, Nit, Praise), and formal review submission (gh pr review).","sidebar":"orchestratorSidebar"},"skills/review-software-architecture":{"id":"skills/review-software-architecture","title":"Skill: Software Architecture Review (Review Software Architecture)","description":"Conduct system-level software architecture reviews assessing component coupling, cohesion, SOLID adherence, API contracts, data model design, operational scalability, and prioritized technical debt.","sidebar":"orchestratorSidebar"},"skills/safety-profiles":{"id":"skills/safety-profiles","title":"Skill: Safety Profiles","description":"Context-appropriate safety guardrails across three dynamic operational levels (Default, Strict, Relaxed). Enforces PII redaction, harmful content blocking, and specialized permissions for authorized security research.","sidebar":"orchestratorSidebar"},"skills/security-audit-codebase":{"id":"skills/security-audit-codebase","title":"Skill: Codebase Security Audit (Security Audit Codebase)","description":"Perform systematic codebase security audits covering regex secret scanning, dependency vulnerability audits (npm audit, pip-audit, cargo audit), injection vulnerability detection, and OWASP Top 10 mitigation.","sidebar":"orchestratorSidebar"},"skills/skill-creator":{"id":"skills/skill-creator","title":"Skill Creator","description":"Create new skills, modify and improve existing skills, and measure skill performance. Use when users want to create a skill from scratch, edit, or optimize an existing skill, run evals to test a skill, benchmark skill performance with variance analysis, or optimize a skill\'s description for better triggering accuracy.","sidebar":"orchestratorSidebar"},"skills/web-artifacts-builder":{"id":"skills/web-artifacts-builder","title":"Web Artifacts Builder","description":"Suite of tools for creating elaborate, multi-component claude.ai HTML artifacts using modern frontend web technologies (React, Tailwind CSS, shadcn/ui). Use for complex artifacts requiring state management, routing, or shadcn/ui components - not for simple single-file HTML/JSX artifacts.","sidebar":"orchestratorSidebar"},"skills/web-search-research":{"id":"skills/web-search-research","title":"Skill: Web Search & Research","description":"Gather current, verified information from the web through systematic search queries, grounding checks, and authoritative source citation. Use for time-sensitive topics, API lookups, and fact-checking.","sidebar":"orchestratorSidebar"},"workflows/agent-loop":{"id":"workflows/agent-loop","title":"Workflow: Agent Loop","description":"Continuous autonomous agent execution loop for open-ended, complex, or emergent multi-step tasks. Iterates through assessment, single tool execution, observation, and state updating until the task goal is fully resolved.","sidebar":"orchestratorSidebar"},"workflows/diagnostic-fix":{"id":"workflows/diagnostic-fix","title":"Workflow: Diagnostic-then-Fix","description":"Structured diagnostic-then-fix workflow using GitNexus knowledge graph and Ariya-4 problem framing. Gathers symptoms, isolates root causes, formulates hypotheses, verifies via reproduction, and applies targeted fixes.","sidebar":"orchestratorSidebar"},"workflows/direct-implementation":{"id":"workflows/direct-implementation","title":"Workflow: Direct Implementation","description":"Rapid single-turn direct implementation workflow for unambiguous, low-risk, single-file code changes and bug fixes with known root causes. Enforces pre-action checks and post-edit sanity verification.","sidebar":"orchestratorSidebar"},"workflows/heartbeat-monitoring":{"id":"workflows/heartbeat-monitoring","title":"Workflow: Heartbeat Monitoring & System Health","description":"Periodic background system health check, task integrity audit, artifact review, and security scan workflow. Generates daily digest summaries and returns HEARTBEAT_OK when state is unchanged.","sidebar":"orchestratorSidebar"},"workflows/pair-programming":{"id":"workflows/pair-programming","title":"Workflow: Interactive Pair Programming","description":"Collaborative, user-driven interactive pair programming workflow. Explains concepts, proposes solutions without unsolicited edits, answers code questions, and applies changes only upon explicit confirmation.","sidebar":"orchestratorSidebar"},"workflows/plan-execute":{"id":"workflows/plan-execute","title":"Workflow: Plan-then-Execute","description":"Multi-phase plan-then-execute workflow for non-trivial features and refactorings. Enforces strict intent gating between read-only planning mode (GitNexus impact analysis, multi-axis solution mapping) and execution mode.","sidebar":"orchestratorSidebar"},"workflows/research-answer":{"id":"workflows/research-answer","title":"Workflow: Research-then-Answer","description":"Systematic web and codebase research workflow for information queries and fact verification. Gathers authoritative sources, executes query chains, evaluates evidence, and synthesizes grounded answers with inline citations.","sidebar":"orchestratorSidebar"},"workflows/spec-driven":{"id":"workflows/spec-driven","title":"Kiro AI-Driven Development Lifecycle: Complete Methodology Instructions","description":"Full lifecycle spec-driven development methodology across three gated phases - Requirements (EARS-format acceptance criteria), Design (architecture, data models, edge cases), and Tasks (phased implementation plan).","sidebar":"orchestratorSidebar"},"workflows/summarization":{"id":"workflows/summarization","title":"Workflow: Session Summarization","description":"Comprehensive session wrap-up and continuity checkpointing workflow. Generates a standalone copy-pasteable initialization prompt, captures decisions, records current setup status, and lists next steps before session end.","sidebar":"orchestratorSidebar"},"workflows/turnaround-builder":{"id":"workflows/turnaround-builder","title":"Workflow: Turnaround Builder","description":"End-to-end prototyping and greenfield application turnaround builder. Generates complete project skeletons, manifests, UI components, backend routes, and verified builds in a single comprehensive pass.","sidebar":"orchestratorSidebar"}}}}')}}]);